function frameSig(r){
  r.description="Signature line: the linked list as a deterministic protocol. In the Signature idiom a linked list is a sealed chain — each node carrying its payload and exactly one published successor, the head published, the tail terminated, no cycles unless declared. Where the public record below describes the conventional node chain, the Signature edition pins its behavior: every splice rewires a published set of links, reversal walks the chain exactly once, and every operation carries its exact cost in the open."+'\n\n'+r.description+'\n\n'+"That is the Signature line on linked lists: the chain never breaks silently and every link is accounted for. The facts above are the standard facts — O(1) splicing at known nodes, O(n) indexing, pointer mechanics — sealed inside a deterministic protocol so a chain built once traverses identically, everywhere.";
  return r;
}
function generate(seed,opts,rnd){
  opts=opts||{};rnd=rnd||prng(seed);
  if(seed>=1&&seed<=ARCHIVE.length){
    return JSON.parse(JSON.stringify(ARCHIVE[seed-1]));
  }
  var g=opts.group&&FIELDS.indexOf(opts.group)>=0?opts.group:null;
  var rec=rnd()<0.5?genComplexity(rnd,seed):genTrace(rnd,seed);
  if(g)rec.group=g;
  if(SIG)frameSig(rec);
  return rec;
}
function sjson(v){return JSON.stringify(v);}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  if(!new RegExp('^'+PREFIX.replace(/-/g,'\\-')+'\\d{6}$').test(r.id||''))e.push('id');
  if(FIELDS.indexOf(r.group)<0)e.push('group');
  if(typeof r.title!=='string'||!r.title.length)e.push('title');
  if(typeof r.description!=='string'||r.description.length<200)e.push('description');
  if(r.src!==GEN_SRC&&r.src!=='reference-authored'&&r.src!=='signature-line')e.push('src');
  if(r.method==='complexity-drill'){
    var hit=null;
    for(var i=0;i<OPS.length;i++)if(OPS[i][0]===r.answer.op)hit=OPS[i];
    if(!hit)e.push('unknown op');
    else if(r.answer.complexity!==hit[1])e.push('complexity mismatch');
  }else if(r.method&&EXEC[r.method]){
    var got;
    try{got=EXEC[r.method](r.test.input);}catch(x){e.push('exec threw');}
    if(got&&sjson(got)!==sjson(r.test.expected))e.push('trace mismatch');
  }else if(!r.method){
    if(!(r.ladder>=1&&r.ladder<=3))e.push('ladder');
  }else{
    e.push('method');
  }
  return {ok:!e.length,errors:e};
}
function driftCheck(rec,sample){
  var seen={};(sample||[]).forEach(function(s){if(s&&s.t)seen[s.t]=1;});
  if(rec&&seen[rec.title])return {ok:false,errors:['duplicate title in archive sample']};
  return {ok:true,errors:[]};
}
var gen={version:'jahdb-linked-list-signature-1.0',generate:generate,validate:validate,driftCheck:driftCheck,fields:FIELDS};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('linked-list-signature',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
